def flatten(d):
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            nested_result = flatten(value)
            for sub_key, sub_value in nested_result.items():
                new_key = f"{key}.{sub_key}"
                result[new_key] = sub_value
        else:
            result[key] = value
    return result
