def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = set()
    result = []
    for row in rows:
        if row.get(key):
            val = row[key]
            if val not in seen:
                seen.add(val)
                result.append(row)
        else:
            # Keep rows missing the key without checking duplicates
            pass
    return result
```

